#!/usr/bin/env bash
# bench-all runs every Part B benchmark against the live stack (docker
# compose up) and leaves raw, timestamped output under bench/out/ plus a
# machine-readable bench/out/results.json -- the source of truth
# docs/BENCHMARKS.md and README's numbers table are written FROM, not
# generated BY (a benchmark doc worth reading explains *why* a number looks
# the way it does; that prose is authored against these raw runs, not
# templated out of them).
#
# Usage: make bench-all
#        ROWS=50000000 ITERS=3 ./scripts/bench-all.sh
set -euo pipefail

ROWS="${ROWS:-10000000}"
ITERS="${ITERS:-5}"
OUT_DIR="bench/out"
mkdir -p "$OUT_DIR"

export TRACELENS_CLICKHOUSE_ADDR="${TRACELENS_CLICKHOUSE_ADDR:-localhost:9000}"
export TRACELENS_CLICKHOUSE_USER="${TRACELENS_CLICKHOUSE_USER:-default}"
export TRACELENS_CLICKHOUSE_PASSWORD="${TRACELENS_CLICKHOUSE_PASSWORD:-tracelens}"

echo "== hardware / environment ==" | tee "$OUT_DIR/00-environment.txt"
{
  echo "date: $(date -u +%Y-%m-%dT%H:%M:%SZ)"
  uname -a
  echo "--- docker info (resources) ---"
  docker info --format 'CPUs: {{.NCPU}}  Memory: {{.MemTotal}}' 2>/dev/null || true
  echo "--- clickhouse version/settings ---"
  docker exec tracelens-clickhouse clickhouse-client --password "$TRACELENS_CLICKHOUSE_PASSWORD" --query "SELECT version()" 2>/dev/null || true
  docker exec tracelens-clickhouse clickhouse-client --password "$TRACELENS_CLICKHOUSE_PASSWORD" --query \
    "SELECT name, value FROM system.settings WHERE name IN ('max_threads','max_memory_usage')" 2>/dev/null || true
} | tee -a "$OUT_DIR/00-environment.txt"

echo "== sampler benchmarks (memory/sec throughput, allocs) ==" | tee "$OUT_DIR/01-sampler-bench.txt"
go test ./internal/sampling/... -run '^$' -bench . -benchmem -benchtime 2s 2>&1 | tee -a "$OUT_DIR/01-sampler-bench.txt"

echo "== sampler load properties (memory/trace, late-span rate, error retention) ==" | tee "$OUT_DIR/02-sampler-load.txt"
go test ./internal/sampling/... -run 'TestBufferMemoryPerInFlightTrace|TestLateSpanRateAtDifferentDecisionWaits|TestErrorsAlwaysRetainedAtOverallLowRate|TestUpweightingRecoversTruePopulation' -v 2>&1 | tee -a "$OUT_DIR/02-sampler-load.txt"

echo "== Drain benchmarks (throughput, template count vs distinct messages) ==" | tee "$OUT_DIR/03-drain-bench.txt"
go test ./internal/logs/... -run '^$' -bench . -benchmem -benchtime 2s 2>&1 | tee -a "$OUT_DIR/03-drain-bench.txt"
go test ./internal/logs/... -run 'TestDrainRecoversKnownTemplateCount|TestTemplateStoreMeasuresStorageSaving' -v 2>&1 | tee -a "$OUT_DIR/03-drain-bench.txt"

echo "== anomaly detector precision/recall ==" | tee "$OUT_DIR/04-anomaly.txt"
go test ./internal/anomaly/... -run TestDetectorPrecisionRecallOnInjectedAnomalies -v 2>&1 | tee -a "$OUT_DIR/04-anomaly.txt"

echo "== storage: compression, codec comparison, batch-size throughput ==" | tee "$OUT_DIR/05-storagebench.txt"
go run ./cmd/storagebench 2>&1 | tee -a "$OUT_DIR/05-storagebench.txt"

echo "== query optimiser passes at scale (rows=$ROWS, iters=$ITERS) ==" | tee "$OUT_DIR/06-querybench.txt"
go run ./cmd/querybench -rows "$ROWS" -iters "$ITERS" 2>&1 | tee -a "$OUT_DIR/06-querybench.txt"

echo "== k6 query-side load ==" | tee "$OUT_DIR/07-k6.txt"
k6 run k6/query-load.js 2>&1 | tee -a "$OUT_DIR/07-k6.txt" || true

echo "== correctness under load ==" | tee "$OUT_DIR/08-correctness.txt"
go run ./cmd/correctnesscheck -traces 500 -spans-per-trace 3 2>&1 | tee -a "$OUT_DIR/08-correctness.txt"

echo "bench-all complete. Raw output in $OUT_DIR/. Author docs/BENCHMARKS.md and README's numbers table from these files."
